css:
.d-cf{position:relative;width:300px;max-width:100%;height:150px;perspective:640px}
.d-cf-item{position:absolute;top:8px;left:50%;width:132px;height:132px;margin-left:-66px;display:flex;flex-direction:column;justify-content:flex-end;gap:2px;padding:10px;box-sizing:border-box;border:1px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink);font:inherit;text-align:left;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform 280ms cubic-bezier(.34,1.56,.64,1),opacity 280ms cubic-bezier(.34,1.56,.64,1),background-color 280ms cubic-bezier(.34,1.56,.64,1),border-color 280ms cubic-bezier(.34,1.56,.64,1),color 280ms cubic-bezier(.34,1.56,.64,1)}
.d-cf-item[data-pos="0"]{transform:translateX(0) rotateY(0) scale(1);z-index:3;background:#2b4b8f;border-color:#2b4b8f;color:var(--paper)}
.d-cf-item[data-pos="-1"]{transform:translateX(-88px) rotateY(34deg) scale(.82);z-index:2;opacity:.72}
.d-cf-item[data-pos="1"]{transform:translateX(88px) rotateY(-34deg) scale(.82);z-index:2;opacity:.72}
.d-cf-item:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-cf-n{font-family:var(--font-mono);font-size:11px;letter-spacing:.08em;opacity:.7}
.d-cf-t{font-size:15px}

init:
root => {
  const items = Array.from(root.querySelectorAll('.d-cf-item'));
  if (!items.length) return;
  const set = i => items.forEach((el, k) => {
    el.dataset.pos = String(k - i);
    el.setAttribute('aria-current', k === i ? 'true' : 'false');
  });
  items.forEach((el, k) => { el.onclick = () => set(k); });
  set(1);
}
